package com.example.homestay.data.entity;
import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.room.*;
@Entity(tableName="rooms") public class Room {
 @PrimaryKey(autoGenerate=true) final long id; final String mongoId; @NonNull final String name; @NonNull final String description; @NonNull final String imageUrl; @NonNull final String location; @NonNull final String address; @NonNull final String amenities; @NonNull final String roomType; final double price; final float rating; final int reviewCount,maxGuests,area,maxSlots; final boolean isAvailable,isFeatured;
 public Room(long id,@Nullable String mongoId,String name,String description,double price,String imageUrl,String location,String address,float rating,int reviewCount,String amenities,int maxGuests,String roomType,int area,int maxSlots,boolean isAvailable,boolean isFeatured){this.id=id;this.mongoId=mongoId;this.name=name;this.description=description;this.price=price;this.imageUrl=imageUrl;this.location=location;this.address=address;this.rating=rating;this.reviewCount=reviewCount;this.amenities=amenities;this.maxGuests=maxGuests;this.roomType=roomType;this.area=area;this.maxSlots=maxSlots;this.isAvailable=isAvailable;this.isFeatured=isFeatured;}
 public long getId(){return id;}public String getMongoId(){return mongoId;}public String getName(){return name;}public String getDescription(){return description;}public double getPrice(){return price;}public String getImageUrl(){return imageUrl;}public String getLocation(){return location;}public String getAddress(){return address;}public float getRating(){return rating;}public int getReviewCount(){return reviewCount;}public String getAmenities(){return amenities;}public int getMaxGuests(){return maxGuests;}public String getRoomType(){return roomType;}public int getArea(){return area;}public int getMaxSlots(){return maxSlots;}public boolean isAvailable(){return isAvailable;}public boolean isFeatured(){return isFeatured;}
 public Room updated(String n,String d,double p,String image,String l,String a,String am,int guests,String type,int area,int slots,boolean available,boolean featured){return new Room(id,mongoId,n,d,p,image,l,a,rating,reviewCount,am,guests,type,area,slots,available,featured);}public Room withRating(float r,int count){return new Room(id,mongoId,name,description,price,imageUrl,location,address,r,count,amenities,maxGuests,roomType,area,maxSlots,isAvailable,isFeatured);}
}
